import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.order = 'YXZ';

  // Create gradient texture using DataTexture
  function createGradientTexture(fromHex, toHex, height = 128) {
    const data = new Uint8Array(height * 4);
    const fromR = parseInt(fromHex.slice(1, 3), 16);
    const fromG = parseInt(fromHex.slice(3, 5), 16);
    const fromB = parseInt(fromHex.slice(5, 7), 16);
    const toR = parseInt(toHex.slice(1, 3), 16);
    const toG = parseInt(toHex.slice(3, 5), 16);
    const toB = parseInt(toHex.slice(5, 7), 16);

    for (let i = 0; i < height; i++) {
      const t = i / (height - 1);
      const r = Math.round(fromR + (toR - fromR) * t);
      const g = Math.round(fromG + (toG - fromG) * t);
      const b = Math.round(fromB + (toB - fromB) * t);
      data[i * 4] = r;
      data[i * 4 + 1] = g;
      data[i * 4 + 2] = b;
      data[i * 4 + 3] = 0xff;
    }

    const texture = new THREE.DataTexture(data, 1, height, THREE.RGBAFormat);
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearFilter;
    texture.needsUpdate = true;
    return texture;
  }

  const gradientTexture = createGradientTexture('#1a1a22', '#121218');

  const material = new MeshStandardNodeMaterial({
    color: 0x8a8a8a,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    anisotropy: 0.6,
    map: gradientTexture,
  });

  const tileWidth = 1.0;
  const tileHeight = 0.62;

  const positions = [
    { x: -1.25, y: 0.435, text: 'HODINKEE', idx: 0 },
    { x: 0, y: 0.435, text: 'MONOCLE', idx: 1 },
    { x: 1.25, y: 0.435, text: 'WALLPAPER', idx: 2 },
    { x: -1.25, y: -0.435, text: 'ESQUIRE', idx: 3 },
    { x: 0, y: -0.435, text: 'WIRED', idx: 4 },
    { x: 1.25, y: -0.435, text: 'FINANCIAL TIMES', idx: 5 },
  ];

  const kickerGroup = new THREE.Group();
  kickerGroup.position.y = 1.045;

  try {
    const kickerText = ctx.fontAtlas.createText('AS FEATURED IN', {
      fontFamily: 'JetBrains Mono',
      fontSize: 9,
      fontWeight: 700,
      letterSpacing: 0.12,
      lineHeight: 1.2,
      color: '#e8ecf2',
      opacity: 1.0,
    });
    if (kickerText.geometry?.center) kickerText.geometry.center();
    kickerGroup.add(kickerText);
  } catch (e) {
    console.warn('Kicker text creation failed:', e);
  }

  group.add(kickerGroup);

  const tiles = [];

  positions.forEach((pos) => {
    const tileGroup = new THREE.Group();
    tileGroup.position.set(pos.x, pos.y, 0);
    tileGroup.userData.idx = pos.idx;

    const geometry = new THREE.BoxGeometry(tileWidth, tileHeight, 0.02);
    const mesh = new THREE.Mesh(geometry, material.clone());
    tileGroup.add(mesh);

    let brandText;
    try {
      brandText = ctx.fontAtlas.createText(pos.text, {
        fontFamily: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 700,
        letterSpacing: 0.08,
        lineHeight: 1,
        color: '#e8ecf2',
        opacity: 0.78,
      });
      if (brandText.geometry?.center) brandText.geometry.center();
      brandText.position.z = 0.015;
      tileGroup.add(brandText);
      tileGroup.userData.brandText = brandText;
    } catch (e) {
      console.warn(`Text creation failed for ${pos.text}:`, e);
    }

    tileGroup.userData.mesh = mesh;
    group.add(tileGroup);
    tiles.push(tileGroup);
  });

  const timeline = gsap.timeline({ paused: false });

  tiles.forEach((tile, i) => {
    const delay = i * 0.08;

    timeline.fromTo(
      tile.position,
      { y: tile.position.y + 0.2 },
      {
        y: tile.position.y,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      delay
    );

    if (tile.userData.brandText?.material) {
      timeline.fromTo(
        tile.userData.brandText.material,
        { opacity: 0 },
        {
          opacity: 0.78,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        delay
      );
    }
  });

  group.userData.handlers = {
    onTileHover: (tileIdx, isHovering) => {
      const tile = tiles[tileIdx];
      if (!tile) return;

      if (tile.userData.brandText?.material) {
        gsap.to(tile.userData.brandText.material, {
          opacity: isHovering ? 1.0 : 0.78,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      }

      gsap.to(tile.position, {
        z: isHovering ? 0.05 : 0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    },
  };

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  const elevation = (35 * Math.PI) / 180;
  keyLight.position.set(3 * Math.cos(elevation), 3 * Math.sin(elevation), 2);
  group.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.4);
  fillLight.position.set(-2, -1, 1);
  group.add(fillLight);

  group.userData.cleanup = () => {
    timeline.kill();
    tiles.forEach((tile) => {
      tile.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    });
    gradientTexture.dispose();
    material.dispose();
  };

  return group;
}
